//! Internal facade consumed by the code generated by `ice-rpc-macros`.
//!
//! The `#[service]` procedural macro emits code that depends on runtime
//! internals. They are grouped here — instead of being re-exported at the crate
//! root — so that the stable public API of `ice-rpc` stays small while the
//! internals can evolve independently.
//!
//! This module is `#[doc(hidden)]` and is **not** part of the public API.
//!
//! # Contents
//!
//! - the wire types and provider primitives used by the generated client /
//!   server (`WireEvent`, `RpcHeader`, `EventKind`, `Sender`, `channel`, …);
//! - the tuning constants and the correlation-id helpers;
//! - the plumbing invoked by `run_provider!` / `#[ice_rpc::main]`;
//! - the dependency re-exports (`rkyv`, `serde_json`, `base64`, …) that the
//!   generated code needs without forcing the user crate to declare them.
//!
//! # Versioning contract
//!
//! This module is a compatibility surface for `ice-rpc-macros` **and**
//! `ice-rpc-rx`, not a public API: its symbols are semver-exempt for the
//! consumers of `ice-rpc`, but **not** for those two crates. Renaming or
//! removing any item below is a breaking change of `ice-rpc-macros`.
//! The `ice-rpc-macros-tests` crate pins every symbol with a dedicated contract
//! test (`gen_facade_symbols_resolve`).

// ── Node liveness ───────────────────────────────────────────────────
pub use crate::node_liveness::{
    is_pid_alive, is_provider, mark_provider, register_node_liveness_watcher,
    unregister_node_liveness_watcher, LIVENESS_POLL_MS,
};

// ── Shutdown ────────────────────────────────────────────────────────
pub use crate::shutdown::{clear_ipc_cleanup, register_ipc_cleanup};

// ── Wire types, provider primitives, correlation ids and constants ───
pub use crate::types::{
    caller_pid_from_cid, channel, fmt_correlation_id, fmt_correlation_id_short, raw_pid_to_u32,
    unbounded_channel, EventKind, NodeId, RpcHeader, Sender, StaticString, WireEvent,
    BLACKBOARD_MAX_READERS, DEFAULT_TOPIC_BUFFER_SIZE, INITIALIZE_ALL_TIMEOUT_SECS,
    INIT_RETRY_INTERVAL_MS, LARGE_PAYLOAD_THRESHOLD, LARGE_TOPIC_BUFFER_SIZE, METHOD_NAME_LEN,
    PROTOCOL_VERSION, PUBLISHER_DEFAULT_MAX_SLICE_LEN, PUBLISHER_LARGE_MAX_SLICE_LEN,
    RPC_CALL_TIMEOUT_SECS, SERVER_READY_POLL_MS, WAITSET_TIMEOUT_US,
};

// Canonical terminal implementations, shared with `ice-rpc-rx` so that the
// inherent `Observable` methods and the `RxStreamExt` default methods cannot
// drift.
pub use crate::types::{collect_values, first_event};

// ── Service traits implemented by the generated code ────────────────
// `ServiceInit` stays public: it is the only one a developer implements.
pub use crate::service_traits::{HttpCallable, ServiceConsumer, ServiceLifecycle, ServiceNamed};

// ── Bootstrap / configuration ───────────────────────────────────────
pub use crate::config::setup_iceoryx2_global_config;

// ── Lifecycle ───────────────────────────────────────────────────────
// Escape hatch for contexts the macros cannot cover (a `main` calling
// `std::process::exit`, the N-API gateway, tests). The documented entry points
// are `#[ice_rpc::main]` and `run_provider!`.
pub use crate::{
    global_cancel_token, init, init_without_ctrl_c, shutdown_and_release, wait_for_shutdown,
    ShutdownGuard,
};

// ── Plumbing invoked by the generated entry points ──────────────────
pub use crate::{_ProviderService, registry_cancel_token, run_provider_inner};

#[cfg(feature = "http")]
pub use crate::start_http_server;

// ── Publish/subscribe transport ─────────────────────────────────────
// Entry points used by the generated client/server (one channel per service,
// correlated by request id, terminal event carried in the stream).
pub use crate::transport::{
    decode_aligned, decode_request, encode_request, native_call, observable_to_responses,
    spawn_native_service, ResponseIter, ServiceDispatcher,
};

// ── Dependency re-exports used by the generated code ────────────────
pub use async_channel;
pub use async_lock;
pub use base64;
pub use futures;
pub use futures_lite;
pub use iceoryx2;
pub use log;
pub use rkyv;
pub use serde_json;
